'use strict';
//
// EVERY SETTING THE STUDIO LETS YOU CHANGE, and what it does.
//
// Generated from an audit of Ikemen GO v1.0.0-rc.5's defaultConfig.ini (the
// v1.0.0 release embeds a byte-identical ini - checked 2026-09-12): the 254
// keys across 17 sections were catalogued against the engine SOURCE rather
// than the ini's own comments, and a second pass checked that work
// adversarially - which turned up 91 corrections and 11 omissions in the first
// pass. `does` and `danger` come from that audit, so they describe what the
// code does rather than what the comment claims.
//
// EXCLUDED ON PURPOSE: key and gamepad bindings (they need a capture UI, not a
// text field - they now have one, Settings > Controls over keylib.js, and it
// stays out of this schema for the same reason), Config.Motif (the theme picker
// owns it), Config.System and
// Config.FirstRun (the exporter owns them - FirstRun especially: leave it at
// rc.5's 1 and the engine discards every binding before the player sees a
// menu), Video.RenderMode (per product - the web build forces WebGL 2), and
// Netplay.PlayerName (identity, not a build setting).
//
// `applies` says which products a setting is written into. A desktop-only
// setting in a web build is at best ignored and at worst a browser workaround
// shipped to a native engine.
//
//
// COMMON: THE ~20% ANYONE ACTUALLY TOUCHES.
//
// `common: true` puts a setting on the Settings page's Common tab. The other
// 106 are still there under All - nothing is hidden - but a page that opens on
// 133 keys, most of which nobody has ever needed, buries the six that people
// came for.
//
// The set is not a guess. It was chosen from two things:
//
// 1. MEASURED. Four real MUGEN builds (Degenerate MUGEN,
//    LEGACY, MUGEN-HYPER-EDITION, Steel MUGEN 2). All four are the same engine
//    and the same stock template - M.U.G.E.N 1.1.0 Beta 1 P1 - so this measures
//    what 1.1 builders change, and says nothing about WinMUGEN or 1.0.
//
//    CORRECTED COUNTS. The first pass parsed the file into a key->value map and
//    reported 124 keys, 79 identical, 45 differing, 13 non-binding. That was
//    wrong: [Music] carries DUPLICATE keys, positionally scoped to the `plugin`
//    line above them (plugin x3, volume x2, rva x2, extensions x2 in every
//    file), so a last-wins map silently collapsed five lines - and lost a real
//    edit, Steel MUGEN 2's mpg123 `volume = 70.0`, which sits under the FIRST
//    plugin while the map kept the second's 100.0. Line-level, the truth is
//    129 key lines, 124 unique (section,key) pairs, 83 IDENTICAL in all four,
//    46 differing, of which 32 are key/joystick bindings - which this Studio
//    deliberately does not expose (they need a capture UI, not a text field).
//    That leaves FOURTEEN keys that real builders demonstrably changed:
//
//      GameWidth, GameHeight, Difficulty, GameSpeed, Time, motif, StartStage,
//      MasterVolume, BGMVolume, WavVolume, KeepAspect, StageFit, SystemFit,
//      and [Music] plugin volume (the one the map ate).
//
//    The fourteenth needs no new entry here: MUGEN's per-plugin music volume is
//    a scale factor on one decoder, and the nearest Ikemen concept is
//    Sound.BGMVolume, which is already common.
//
//    Every one of those with an Ikemen counterpart is marked common here.
//    `motif` is not: the theme picker owns it. StageFit/SystemFit have no
//    direct Ikemen key - the aspect handling is KeepAspect plus the
//    FightAspect pair, and only KeepAspect is a plain on/off anyone reaches for.
//
// 2. INTENT. The rest are what a person means by "set up my game": how hard,
//    how long, how many rounds, how many continues, how big, how loud, which
//    fight mechanics are on, how large a team can be. These are the questions
//    a build owner answers once, deliberately.
//
// A NOTE ON WHAT THIS TAB IS NOT FOR. "You locked our common palette and
// portrait settings behind advanced settings" was about the per-character
// REPAIR BUTTONS - fix palette slots, the color-pick fix, add lifebar portrait
// - not about anything in this file. Those live on the character card and are
// now on their own always-visible line. Engine config keys like PaletteMax were
// added here in response and then reverted: they are not what anyone reaches
// for when a character renders wrong.
//
// NOTHING FLAGGED `advanced` IS EVER COMMON, and that is checked rather than
// trusted - the two lists are disjoint by construction.
//
// Regenerate with `node scripts/gen-settings.js`.

const SETTINGS = [
  { sec: 'Options', key: 'Difficulty', common: true, type: 'int', def: '5', applies: 'both', group: 'AI', min: 1, max: 8, opts: [['1', '1 - easiest'], ['2', '2'], ['3', '3'], ['4', '4'], ['5', '5 - default'], ['6', '6'], ['7', '7'], ['8', '8 - hardest']], does: 'Default AI level for CPU-controlled fighters: start.lua\'s f_difficulty returns this value plus the Arcade AI-ramp offset and passes it to setCom, which clamps the final level to 0-8; it is also stamped into hiscore records as AILevel (hiscore_rank.go) and seeds the pause/training menu\'s AI level.' },
  { sec: 'Options', key: 'Life', common: true, type: 'float', def: '100', applies: 'both', group: 'Match rules', min: 10, max: 300, does: 'Percentage multiplier applied to every character\'s lifeMax once per round in system.go SetupCharRoundStart (`lmax *= s.cfg.Options.Life / 100`), then floored and forced to at least 1. It scales the character\'s own life/lifeMax value, so it stacks with per-character life overrides from select.def.', danger: '0 or a negative value drives every lifeMax to the Max(1, ...) floor, so every character dies to a single point of damage.' },
  { sec: 'Options', key: 'Time', common: true, type: 'int', def: '99', applies: 'both', group: 'Match rules', min: -1, max: 1000, avoid: [[0, 'Time = 0 is read as time-over on frame one, so every round ends the instant it starts. Use -1 for no timer.']], does: 'Round time in displayed counts. start.f_setRounds multiplies it by fight.def\'s time.framespercount and calls setRoundTime, which stores sys.maxRoundTime (adding framespercount-1 first when Config.LegacyTime is on).', danger: 'Time = 0 is accepted by both the menu and the engine and is fatal to play: curRoundTime starts at 0 and system.go treats `curRoundTime == 0` as time-over, so every round ends the instant it begins. The Studio should offer -1 and >=1 only.' },
  { sec: 'Options', key: 'GameSpeed', common: true, type: 'int', def: '0', applies: 'both', group: 'Match rules', min: -9, max: 9, does: 'Sets the game LOGIC tick rate, not an animation multiplier: system.go gameLogicSpeed() returns Max(1, 60 + GameSpeed*GameSpeedStep) ticks per second. Lua setGameSpeed() writes straight into this config field at runtime (script.go), which is how the -speed and -speedtest command-line flags work.', danger: 'Non-zero speed is explicitly unfinished under rollback netcode: gameRenderSpeed() forces 60 for any rollback session and carries the source TODO "Rollback should render at Framerate but sync at Gamespeed".' },
  { sec: 'Options', key: 'GameSpeedStep', type: 'int', def: '5', applies: 'both', group: 'Match rules', min: 1, max: 60, does: 'Size in ticks/second of one GameSpeed step; it is the multiplier in gameLogicSpeed()\'s `60 + GameSpeed*GameSpeedStep`. main.lua also divides by it to convert a -speedtest target multiplier back into a GameSpeed value.', danger: 'Step 60 with GameSpeed 9 asks for 600 logic ticks per second (unplayable and CPU-bound, and in the browser it will simply fall behind); with GameSpeed -9 the result goes negative and is floored to 1 tick/second, effectively freezing the…' },
  { sec: 'Options', key: 'Match.Wins', common: true, type: 'int', def: '2', applies: 'both', group: 'Match rules', min: 1, max: 10, does: 'Rounds needed to win the match, used only when the OPPOSING side is in Single mode. start.f_setRounds picks single/simul/tag wins by the enemy team\'s mode and calls setMatchWins(side, n) -> sys.matchWins[side].' },
  { sec: 'Options', key: 'Match.MaxDrawGames', type: 'int', def: '1', applies: 'both', group: 'Match rules', min: -1, max: 10, does: 'Per-side draw allowance, pushed to sys.maxDraws via setMatchMaxDrawGames. system.go maxDrawsReached() is `limit >= 0 && draws >= limit`, so a negative value disables the limit; once reached the side is flagged in effectiveLoss and the match ends.', danger: '0 means the very first draw immediately ends the match as a loss for both sides. Also note system.go:3228 resolves match-over on draws with `||` and carries the source TODO "Maybe this should be &&", so asymmetric per-side draw limits…' },
  { sec: 'Options', key: 'Credits', common: true, type: 'int', def: '10', applies: 'both', group: 'Match rules', min: 0, max: 99, avoid: [[0, 'Credits = 0 becomes setCredits(-1), which the engine reads as UNLIMITED continues - the opposite of what it looks like. Use 1 for a single credit.']], does: 'Starting continue allowance. main.f_setCredits calls setCredits(Credits - 1), i.e. the engine\'s sys.credits is one LESS than this value. motif.go gates the continue screen on `sys.credits == -1 || sys.credits > 0` and decrements on each continue; the attract-mode coin key increments it.', danger: 'Credits = 0 does NOT mean \'no continues\'. It becomes setCredits(0-1) = -1, which motif.go reads as UNLIMITED continues, while options.lua labels the same value "Disabled".' },
  { sec: 'Options', key: 'QuickContinue', type: 'bool', def: '0', applies: 'both', group: 'Match rules', does: 'When continuing after a loss, skips the character select screen and drops straight back into the rematch. start.lua only rebuilds the select state in the `not t.quickcontinue` branch.' },
  { sec: 'Options', key: 'AutoGuard', common: true, type: 'bool', def: '0', applies: 'both', group: 'Fight mechanics', does: 'char.go\'s per-frame action() calls `c.setASF(ASF_autoguard)` on every character while this is true; the flag makes the guard checks at char.go:10848 and 11962 treat the character as guarding without a held back input.', danger: 'Applies to every character on the field, including AI opponents and helpers - turning it on makes CPU fighters block everything too, which can make an arcade ladder unwinnable if the build was balanced with it off.' },
  { sec: 'Options', key: 'GuardBreak', common: true, type: 'bool', def: '0', applies: 'both', group: 'Fight mechanics', does: 'Enables guard-break mechanics (data/guardbreak.zss) and the fight.def [Guardbar] elements. The path is entirely Lua: main.lua seeds main.fightscreen.guardbar from this key and setFightScreenElements writes sys.fightScreen.guardbar, which is what char.guardBreakEnabled() returns.', danger: 'Enabling it without data/guardbreak.zss in [Common] States, or without a [Guardbar] group in the motif\'s fight.def, gives a mechanic with no feedback or no mechanic at all - the Studio should tie this toggle to the presence of both.' },
  { sec: 'Options', key: 'Dizzy', common: true, type: 'bool', def: '0', applies: 'both', group: 'Fight mechanics', does: 'Enables dizzy/stun mechanics (data/dizzy.zss) and fight.def [Stunbar] rendering, via the same Lua route: main.lua -> setFightScreenElements -> sys.fightScreen.stunbar, which is what char.dizzyEnabled() returns.', danger: 'Same coupling as GuardBreak: it needs data/dizzy.zss in [Common] States and a [Stunbar] group in fight.def or it does nothing visible.' },
  { sec: 'Options', key: 'RedLife', common: true, type: 'bool', def: '1', applies: 'both', group: 'Fight mechanics', does: 'Enables red-life (recoverable damage) mechanics and the fight.def [Lifebar] red element, again via main.lua -> setFightScreenElements -> sys.fightScreen.redlifebar, read by char.redLifeEnabled().' },
  { sec: 'Options', key: 'Team.Duplicates', type: 'bool', def: '1', applies: 'both', group: 'Team modes', does: 'Purely a character-select rule implemented in Lua (start.lua, many sites): when false, a character already chosen by that side is blocked from being selected again; \'randomselect\' cells are always exempt. The Go engine never reads this key.', danger: 'Turning it off on a small roster can make a large team size unselectable - start.lua blocks cursor movement onto reserved slots, so a 4-character Simul team on a 3-character roster deadlocks the select screen.' },
  { sec: 'Options', key: 'Team.LifeShare', common: true, type: 'bool', def: '0', applies: 'both', group: 'Team modes', does: 'Two different behaviors depending on team mode, both in system.go SetupCharRoundStart: for Simul/Tag it replaces each member\'s lifeMax with the team\'s AVERAGE max life; for Turns it divides lifeMax by the roster size (numTurns).', danger: 'In Turns the divisor is the team size, so a 4-character Turns team with LifeShare on gives every member a quarter of their normal life - combined with a large Turns.Max this becomes a one-hit-kill ladder.' },
  { sec: 'Options', key: 'Team.PowerShare', type: 'bool', def: '1', applies: 'both', group: 'Team modes', does: 'char.powerOwner() redirects every teammate\'s power meter reads/writes to the team leader\'s character, and SetupCharRoundStart sets the whole team\'s powerMax to the highest member\'s. fightscreen.go then skips drawing the non-leader power bars for Simul/Tag.' },
  { sec: 'Options', key: 'Team.SingleVsTeamLife', type: 'float', def: '100', applies: 'both', group: 'Team modes', min: 10, max: 300, does: 'Percent multiplier on lifeMax applied in SetupCharRoundStart to a side whose own mode is TM_Single and whose OPPONENT\'s mode is Simul, Turns or Tag. It multiplies on top of Options.Life.', danger: 'Values below ~50 can push lifeMax to the Max(1,...) floor when combined with a low Options.Life. Fractional values are also risky to write through our Studio\'s rules patcher, whose regex only replaces an integer run in the existing line.' },
  { sec: 'Options', key: 'Simul.Min', type: 'int', def: '2', applies: 'both', group: 'Team modes', min: 2, max: 4, does: 'Lower bound on Simul team size. main.lua stores it as main.numSimul[1]; the select screen refuses to shrink a Simul team below it and random team-size picks use math.random(Min, Max).', danger: 'normalize() clamps Simul.Max BEFORE Simul.Min, using the raw Min as Max\'s lower bound (config.go lines 331-332).' },
  { sec: 'Options', key: 'Simul.Max', common: true, type: 'int', def: '4', applies: 'both', group: 'Team modes', min: 2, max: 4, does: 'Upper bound on Simul team size (main.numSimul[2]); caps the select screen\'s team-size cursor and the upper end of random team sizes.', danger: 'Same clamp-ordering hole as Simul.Min - an out-of-range Min can push this above the engine\'s hard 4-per-side character array. Validate in the Studio rather than trusting normalize().' },
  { sec: 'Options', key: 'Simul.Match.Wins', type: 'int', def: '2', applies: 'both', group: 'Team modes', min: 1, max: 10, does: 'Rounds needed to win when the OPPOSING side is in Simul mode; start.f_setRounds selects it by enemy team mode and feeds setMatchWins.' },
  { sec: 'Options', key: 'Simul.LoseOnKO', type: 'bool', def: '1', applies: 'both', group: 'Team modes', does: 'In system.go\'s KO check, a Simul side loses the round as soon as any one member is KO\'d - but ONLY when that member\'s aiLevel is 0, i.e. a human-controlled slot.' },
  { sec: 'Options', key: 'Tag.Min', type: 'int', def: '2', applies: 'both', group: 'Team modes', min: 2, max: 4, does: 'Lower bound on Tag team size (main.numTag[1]); bounds the select screen team-size cursor and random team sizes.', danger: 'Same normalize() clamp-ordering hole as Simul: Tag.Max is clamped against the raw Tag.Min first (config.go 333-334), so an out-of-range Min can leave Tag.Max above the engine\'s 4-slots-per-side limit.' },
  { sec: 'Options', key: 'Tag.Max', common: true, type: 'int', def: '4', applies: 'both', group: 'Team modes', min: 2, max: 4, does: 'Upper bound on Tag team size (main.numTag[2]).', danger: 'See Tag.Min - validate Min <= Max <= 4 in the Studio.' },
  { sec: 'Options', key: 'Tag.Match.Wins', type: 'int', def: '2', applies: 'both', group: 'Team modes', min: 1, max: 10, does: 'Rounds needed to win when the OPPOSING side is in Tag mode; selected in start.f_setRounds and applied via setMatchWins.' },
  { sec: 'Options', key: 'Tag.LoseOnKO', type: 'bool', def: '0', applies: 'both', group: 'Team modes', does: 'In the same KO check, a Tag side loses the round as soon as any member is KO\'d. Unlike the Simul branch there is no aiLevel condition, so it applies to AI-controlled partners too.' },
  { sec: 'Options', key: 'Tag.TimeScaling', type: 'float', def: '1.0', applies: 'both', group: 'Team modes', does: 'When either side is in Tag mode, start.f_setRounds multiplies fight.def\'s time.framespercount by (1 + (maxTeamSize - 1) * TimeScaling), floors the result at the unscaled frames, and calls setTimeFramesPerCount.', danger: 'Only float key in this section with a fractional shipped default, so it is the one most exposed to our Studio\'s rules patcher (vfs.js applyRulesToConfig): its regex replaces only the `-?[0-9]+` run, so writing 2 over `Tag.TimeScaling =…' },
  { sec: 'Options', key: 'Turns.Min', type: 'int', def: '2', applies: 'both', group: 'Team modes', min: 1, max: 4, does: 'Lower bound on Turns roster size (main.numTurns[1]); bounds the select screen\'s team-size cursor and random team sizes.' },
  { sec: 'Options', key: 'Turns.Max', common: true, type: 'int', def: '4', applies: 'both', group: 'Team modes', min: 1, max: 4, does: 'Upper bound on Turns roster size (main.numTurns[2]); start.lua caps the built team with math.min(numTurns, Turns.Max) and the select screen draws main.numTurns[2] member slots.', danger: 'Rounds-to-win in Turns is always the enemy team size (start.f_setRounds overrides all the Wins keys), so a large Turns.Max directly means a very long match - Turns.Max 8 is a first-to-8.' },
  { sec: 'Options', key: 'Turns.Recovery.Base', type: 'float', def: '0', applies: 'both', group: 'Team modes', min: 0, max: 100, does: 'Percent of lifeMax handed back unconditionally to the surviving winner between rounds. Implemented in data/system.zss: at roundState 4 the winner computes round(lifeMax*Base/100 + lifeMax*Bonus/100 * timeRatio) and drips it back at up to 3 points per tick.', danger: 'It is implemented in data/system.zss, so a build whose [Common] States list drops system.zss loses Turns life recovery entirely with no error.' },
  { sec: 'Options', key: 'Turns.Recovery.Bonus', type: 'float', def: '27.5', applies: 'both', group: 'Team modes', min: 0, max: 100, does: 'Percent of lifeMax awarded to the winner scaled by the fraction of round time left: the system.zss formula adds `lifeMax*Bonus/100 * timeRemaining/(timeRemaining+timeElapsed)`, and treats an infinite timer (timeRemaining < 0) as a full-ratio 1.0.', danger: 'Fractional default, so the same Studio rules-patcher caveat as Tag.TimeScaling applies: the integer-only regex in vfs.js applyRulesToConfig would rewrite `27.5` to e.g. `40.5` rather than `40`.' },
  { sec: 'Video', key: 'GameWidth', common: true, type: 'int', def: '1280', applies: 'both', group: 'Display', min: 160, max: 7680, webDef: '854', does: 'The engine\'s internal render resolution width. src/config.go:388 copies it to sys.gameWidth (unless the -width command-line flag overrides), which becomes sys.scrrect[2] via setGameSize(); every framebuffer, the post-process chain, the debug-text viewport and the default window size are sized from…', danger: 'Nothing validates it. 0 or a negative value gives a zero/negative-size window and a divide-by-zero aspect.' },
  { sec: 'Video', key: 'GameHeight', common: true, type: 'int', def: '720', applies: 'both', group: 'Display', min: 120, max: 4320, webDef: '480', does: 'Internal render resolution height; the exact counterpart of GameWidth (src/config.go:394 -> sys.gameHeight -> sys.scrrect[3]). Overridable by the -height command-line flag.', danger: 'Same as GameWidth: unvalidated, zero/negative breaks the window and the aspect math, and the resulting GameWidth:GameHeight ratio silently becomes the menu/screenpack aspect. Also tagged sync:"strict".' },
  { sec: 'Video', key: 'WindowWidth', type: 'int', def: '0', applies: 'desktop', group: 'Display / Window', min: 0, max: 7680, advanced: 'It only changes the OS window size on a build the user can already resize by dragging (SetResizable(true) is called unconditionally at system_sdl.go:247), it is meaningless on web, and the OR-guard makes it a footgun. Let GameWidth/GameHeight drive the window and leave this key out of the UI.', does: 'Overrides the desktop window\'s pixel width. src/system_sdl.go:72 - if either WindowWidth or WindowHeight is > 0, BOTH w2 and h2 are replaced by the configured values; otherwise the window keeps the size newWindow() was called with, which is GameWidth/GameHeight.', danger: 'Setting one of the pair and leaving the other at 0 creates a zero-dimension window - a real, easy-to-hit misconfiguration. If the Studio exposes this at all it must write both values or neither.' },
  { sec: 'Video', key: 'WindowHeight', type: 'int', def: '0', applies: 'desktop', group: 'Display / Window', min: 0, max: 4320, advanced: 'Same as WindowWidth: cosmetic on desktop only, user-adjustable by dragging the window, and dangerous to expose independently.', does: 'Desktop window pixel height; the counterpart of WindowWidth, applied by the same combined guard at src/system_sdl.go:72-74.', danger: 'Same coupling bug as WindowWidth - setting only one of the pair yields a zero-size dimension.' },
  { sec: 'Video', key: 'Fullscreen', common: true, type: 'bool', def: '0', applies: 'desktop', group: 'Display / Window', does: 'Starts the desktop build maximized to the desktop display mode. src/system_sdl.go:69 computes `fullscreen = cfg.Video.Fullscreen && !forceWindowed` (the -windowed flag wins), then line 107 adds sdl.WINDOW_FULLSCREEN_DESKTOP, moves the window to 0,0 and hides the cursor.', danger: 'Low. A user who sets it and hits a black screen can still recover with the -windowed flag or the in-game options menu (options.lua:832 calls toggleFullscreen).' },
  { sec: 'Video', key: 'Borderless', type: 'bool', def: '0', applies: 'desktop', group: 'Display / Window', advanced: 'Its documented purpose (borderless fullscreen) is already what Fullscreen does in rc.5, and its actual effect - a chromeless draggable-by-nothing window - is a trap rather than a feature. Leave it at 0 and out of the UI.', does: 'Removes the window\'s title bar and border. In the windowed path (src/system_sdl.go:110) it adds sdl.WINDOW_BORDERLESS instead of sdl.WINDOW_RESIZABLE, and line 138 calls SetBordered(false). In the fullscreen path (line 132) it additionally forces SetBordered(false) and SetSize(desktopW, desktopH).', danger: 'A borderless non-fullscreen window has no close button and no title bar to drag. Combined with a WindowWidth larger than the display, that is a window the user cannot move or close by mouse. Worth a warning if exposed.' },
  { sec: 'Video', key: 'RGBSpriteBilinearFilter', type: 'bool', def: '1', applies: 'both', group: 'Display', does: 'Chooses the GL min/mag filter for textures created from RAW (non-indexed) sprite data. src/image.go:867 passes it as the `filter` argument of gfx.newTexture in Sprite.SetRaw - the path used for RGB/RGBA sprites (SFF v2 truecolor, PNG-backed art).', danger: 'None mechanically. Aesthetically it is load-bearing: 1 softens hand-drawn truecolor art, and it is the reason a scaled RGBA effect can look blurry next to a crisp indexed sprite in the same frame.' },
  { sec: 'Video', key: 'Framerate', type: 'int', def: '60', applies: 'both', group: 'Performance', min: 1, max: 480, does: 'The target render/frame-pacing rate. src/system.go:4412 gameRenderSpeed() returns it, and src/system.go:2910 derives the per-frame logic step as gameLogicSpeed()/gameRenderSpeed() - so raising it renders more frames and advances the simulation in fractional steps rather than speeding the match up.', danger: 'Very low values make the simulation advance in huge steps per drawn frame; very high values on the web build multiply GL marshalling garbage and GC pauses - the exact failure the rAF cap in system_js.go was written to prevent, and the one…' },
  { sec: 'Video', key: 'VSync', common: true, type: 'int', def: '1', applies: 'desktop', group: 'Display', opts: [['-1', 'Adaptive'], ['0', 'Off'], ['1', 'On'], ['2', 'Every 2nd refresh'], ['3', 'Every 3rd refresh']], does: 'The swap interval. src/system.go:465 applies it after gfx.Init() (with an in-source comment that it must be set after Init or the ini is ignored); on GL it reaches sdl.GLSetSwapInterval (render_gl33.go:2253).', danger: 'Only that -1 flips its meaning between backends (adaptive on GL, off on Vulkan), and that VSync = 0 on desktop lets the render loop free-run. Nothing crashes.' },
  { sec: 'Video', key: 'MSAA', type: 'enum', def: '0', applies: 'desktop', group: 'Display', opts: [['0', 'Off'], ['2', '2x'], ['4', '4x'], ['6', '6x'], ['8', '8x'], ['16', '16x'], ['32', '32x']], does: 'Multisample anti-aliasing sample count for the main framebuffer. src/config.go:398 copies it to sys.msaa; render_gl33.go builds a multisampled renderbuffer and resolves it with a BlitFramebuffer in EndFrame when sys.msaa > 0 (render_gl33.go:733, 1088).', danger: 'High sample counts cost real fill rate at 1080p. The silent reset means a typo like MSAA = 3 looks accepted but disables AA. It is forced off on two of the backends regardless of what is written.' },
  { sec: 'Video', key: 'WindowCentered', type: 'bool', def: '1', applies: 'desktop', group: 'Display / Window', advanced: 'Cosmetic window placement that does not affect the game, is a no-op on the web build, and does not even do what its comment says. Not something a person building a MUGEN game needs in a content manager.', does: 'Re-applies a centered position to the desktop window. In newWindow the centered coordinates are computed unconditionally (`x, y = (desktopW-w2)/2, (desktopH-h2)/2`, system_sdl.go:77) and passed straight to sdl.CreateWindow; the key then only gates a redundant SetPosition(x, y) in the windowed…', danger: 'None.' },
  { sec: 'Video', key: 'ExternalShaders', type: 'string', def: '', applies: 'both', group: 'Display', does: 'An ordered list of post-processing shader paths, given without file extension. src/system.go:423-432 loads them BEFORE gfx.Init(), reading <path>.vert and <path>.frag for OpenGL or <path>.vert.spv / <path>.frag.spv for Vulkan.', danger: 'This is the most dangerous key in the section. A path that does not resolve hits chk(err) on the os.ReadFile (system.go:434-449) and the engine PANICS at startup - before the window is usable - so a mistyped or unshipped shader is a build…' },
  { sec: 'Video', key: 'WindowScaleMode', type: 'bool', def: '1', applies: 'both', group: 'Display', opts: [['0', 'Nearest - sharp pixels'], ['1', 'Bilinear - smoothed']], does: 'The filter used for the final blit of the rendered framebuffer to the window. render_gl33.go:1095 selects gl.LINEAR when true and gl.NEAREST when false; our WebGL renderer does the same at render_webgl.go:696.', danger: 'None. Note only that Vulkan has no equivalent - there is no WindowScaleMode read anywhere in render_vk.go, so the key is silently inert on a Vulkan desktop build.' },
  { sec: 'Video', key: 'FightAspectWidth', type: 'int', def: '-1', applies: 'both', group: 'Display / Aspect', does: 'With FightAspectHeight, selects the aspect ratio used during a match (as opposed to menus). src/system.go:584 getFightAspect(): -1,-1 uses the stage\'s localcoord; positive w,h uses that custom ratio; anything else falls through to getMotifAspect(), i.e. the GameWidth:GameHeight ratio.', danger: 'It is tagged sync:"strict" and IS enforced online, but indirectly: src/netplay.go:1439-1447 skips a direct comparison of GameWidth/GameHeight/FightAspectWidth/FightAspectHeight and instead compares a derived key from…' },
  { sec: 'Video', key: 'FightAspectHeight', type: 'int', def: '-1', applies: 'both', group: 'Display / Aspect', does: 'The height half of the fight aspect pair; only ever evaluated jointly with FightAspectWidth in getFightAspect(), applyFightAspect() and the model aspect correction. Same three code paths (src/system.go:584, 592, 651 and src/model.go:2353).', danger: 'Same netplay strict-sync consequence as FightAspectWidth - the derived aspect key must match between peers or the session is refused.' },
  { sec: 'Video', key: 'KeepAspect', common: true, type: 'bool', def: '1', applies: 'both', group: 'Display / Aspect', opts: [['1', 'Preserve aspect (black bars)'], ['0', 'Stretch to fill']], does: 'When true the final viewport is letterboxed/pillarboxed to preserve the game\'s aspect ratio inside the window; when false the image is stretched to fill. Window.GetScaledViewportSize (src/system_sdl.go:211, mirrored in our src/system_js.go:148) returns the full window early if it is false.', danger: 'Low, but it is not the pure cosmetic toggle the comment implies - turning it off changes how the motif is scoped and how overlays are composed, so a screenpack tuned with KeepAspect = 1 can shift its element positions at 0.' },
  { sec: 'Video', key: 'EnableModel', type: 'bool', def: '1', applies: 'desktop', group: 'Renderer', advanced: 'Not a creative choice: either the build ships glTF stages and needs it, or it does not and the setting is invisible. The Studio knows which stages it packed and should derive this rather than asking.', does: 'Enables the 3D glTF model pipeline. render_gl33.go:608 copies it to r.enableModel; if true the backend compiles the model shaders and, if that compile fails, quietly turns itself back off (render_gl33.go:656-659).', danger: 'Setting it to 0 on a desktop build makes glTF-model stages render without their models - the stage looks empty or broken rather than erroring. Setting it to 1 costs shader compilation and a draw pass even for a build with no 3D stages.' },
  { sec: 'Video', key: 'EnableModelShadow', type: 'bool', def: '1', applies: 'desktop', group: 'Renderer', advanced: 'Same reasoning as EnableModel. The web build draws 3D-model stages but never their shadows (WebGL2 has no geometry shaders or cube-map arrays), so this matters to a desktop export only. Expose it beside EnableModel as a quality option, not in a general video panel.', does: 'Enables shadow-map rendering for 3D models. render_gl33.go:609 -> r.enableShadow, which gates the shadow framebuffer and shadow map setup (render_gl33.go:508, 537, 1521) and the shadow pass inside the model draw (render_gl33.go:839).', danger: 'None beyond cost - it is the expensive half of the model pipeline, so it is the right thing to turn off first on weak hardware. It has no effect whatsoever when EnableModel = 0.' },
  { sec: 'Video', key: 'RendererDebugMode', type: 'bool', def: '0', applies: 'desktop', group: 'Diagnostics', advanced: 'A pure engine-diagnostic switch for someone debugging the renderer, not for someone assembling a game. It is also inert on our web build - render_webgl.go never reads it. Keep it at 0 and out of the UI.', does: 'Turns on the graphics API\'s validation/debug output. On OpenGL 3.3 it requests a debug context (sdl.GL_CONTEXT_DEBUG_FLAG at system_sdl.go:96) and calls r.EnableDebug() (render_gl33.go:611). On Vulkan it enables the validation layers and the debug messenger (render_vk.go:1433, 1512).', danger: 'It measurably slows rendering - the ini\'s own warning is accurate - and on Vulkan it requires the Vulkan SDK to be installed for validation messages to appear at all, so on a player\'s machine it costs performance and produces nothing.' },
  { sec: 'Video', key: 'ImageSuballocThresholdKB', type: 'int', def: '1024', applies: 'desktop', group: 'Renderer / Vulkan memory', advanced: 'A GPU memory-allocator tuning knob for an experimental backend, with no visible effect on the game and a documented behavior the code does not honor. Nobody assembling a MUGEN build should be asked about it - leave it at the default.', does: 'Vulkan only. Images at or below this size are carved out of a shared memory block instead of getting their own vkAllocateMemory; it becomes VulkanAllocator.smallImageThreshold (render_vk.go:5125). src/config.go:376 resets a NEGATIVE value to 256.', danger: 'Only memory-pressure tuning: a very large threshold pools big textures and can waste memory in partly-filled blocks; a small one adds dedicated allocations. It cannot corrupt a build, and it is entirely inert unless RenderMode = Vulkan 1.3.' },
  { sec: 'Video', key: 'ImageSuballocBlockSizeMB', type: 'int', def: '128', applies: 'desktop', group: 'Renderer / Vulkan memory', advanced: 'Explicitly a memory tuning knob for the Vulkan allocator, invisible in gameplay, self-limiting, and meaningless on the web build. Not content-manager material.', does: 'Vulkan only. The size of each block in the image suballocation pool; becomes VulkanAllocator.blockSize (render_vk.go:5129).', danger: 'Same class as the threshold: a memory/allocation-count tradeoff on an experimental backend. The 25% heap cap means an absurd value is silently reduced rather than failing, so it cannot break a build. Inert unless RenderMode = Vulkan 1.3.' },
  { sec: 'Config', key: 'Players', type: 'int', def: '4', applies: 'both', group: 'Controls', min: 1, max: 8, does: 'The number of player-controlled slots. config.sysSet() (src/config.go:392) loops i = 1..Players and builds one KeyConfig and one joystick KeyConfig per slot from [Keys_Pn]/[Joystick_Pn]; slots without a section get KeyConfig{Joy:-1}.', danger: 'Set it below the number of [Keys_Pn] sections shipped and the extra sections are silently ignored - those players simply have no input. Set it below 4 and versuscoop disappears from the mode list with no explanation.' },
  { sec: 'Config', key: 'Language', common: true, type: 'string', def: 'en', applies: 'both', group: 'Localization', does: 'Two-letter ISO 639-1 code that selects localized [<lang>.section] blocks. Go\'s SelectedLanguage() (src/iniutils.go:19) resolves the literal "system" against the OS locale (GetUserDefaultLocaleName on Windows), strips it to two letters, and falls back to "en"; ResolveLangSectionName(s) then prefer…', danger: 'Setting "system" makes character DEF localization and select.def localization silently stop working (see commentWrong) - the game does not error, it just quietly uses the unprefixed sections.' },
  { sec: 'Config', key: 'AfterImageMax', type: 'int', def: '512', applies: 'both', group: 'Engine limits', min: 0, max: 4096, advanced: 'A pure memory/draw-budget knob with no gameplay meaning - the comment itself frames it as "set to a lower number to save memory". A build author has no way to reason about the right number, and the engine derives nothing useful from a user choice here.', does: 'Per-player, per-frame budget for afterimage sprite draws. AfterImage.recAndCue (src/char.go:1547) breaks out of its trail loop once sys.afterImageCount[playerNo] reaches this value, and the counter is incremented per queued sprite (char.go:1586) and reset to 0 every frame (system.go:2743).', danger: 'Lowering it visibly truncates every character\'s afterimage trail with no warning and no console message. Negative values are accepted and silently kill afterimages, because normalize()\'s clamp for this key is commented out.' },
  { sec: 'Config', key: 'ExplodMax', type: 'int', def: '512', applies: 'both', group: 'Engine limits', min: 0, max: 8192, advanced: 'Memory tuning, not a design decision. Nothing about the game a builder is making changes when this moves, and there is no signal to tune against.', does: 'Per-player cap on live explods. Char.spawnExplod (src/char.go:7013) returns nil the moment len(sys.explods[playerNo]) reaches this value. Hitsparks are explods, so this covers hit effects too.', danger: 'Unlike helpers and projectiles, hitting this limit is completely silent - spawnExplod just returns nil with no console warning.' },
  { sec: 'Config', key: 'HelperMax', type: 'int', def: '56', applies: 'both', group: 'Engine limits', min: 0, max: 4096, advanced: 'Presented as a memory knob, and a builder cannot judge the right value. More importantly it is not safe to move casually - see danger. Ship the default.', does: 'Two jobs. First, it caps helper slots per player: Char.helperInit (src/char.go:6872) refuses to append a new helper once the index exceeds HelperMax (index 0 is the root, so it is effectively HelperMax helpers) and writes "Reached limit of N helpers" to the console.', danger: 'It is not a pure memory knob. Because it seeds lastCharId, changing it shifts the numeric IDs the engine hands out to players and helpers.' },
  { sec: 'Config', key: 'ProjectileMax', type: 'int', def: '256', applies: 'both', group: 'Engine limits', min: 0, max: 4096, advanced: 'Memory tuning with no design meaning, same class as ExplodMax. The default is generous enough that no normal content hits it.', does: 'Per-player cap on live projectiles. Char.spawnProjectile (src/char.go:7558) refuses to create one past the limit and appends "Reached limit of N projectiles. New projectile creation skipped" to the console.', danger: 'A low value makes projectile-heavy characters silently stop firing mid-combo; at least this one does log a warning, unlike explods and texts.' },
  { sec: 'Config', key: 'PaletteMax', type: 'int', def: '100', applies: 'both', group: 'Engine limits', min: 1, max: 256, does: 'The number of palette slots the engine allocates and searches per character. It sizes the palInfo map (char.go:3163), bounds palette-number validation in the DEF reader (char.go:3895), image.go:544 and script.go:6191, bounds ACT loading (char.go:4388, image.go:2181, image.go:2019-2023), and…', danger: 'Lowering it below a character\'s palette count silently drops the extra palettes and can make a select-screen color pick land on a slot that no longer exists.' },
  { sec: 'Config', key: 'TextMax', type: 'int', def: '128', applies: 'both', group: 'Engine limits', min: 0, max: 4096, advanced: 'Memory tuning knob, exactly as the comment says. No build-level meaning.', does: 'Per-player cap on live Text sprites created by the Text state controller. Char.spawnText (src/char.go:7204) returns nil once len(sys.chartexts[playerNo]) reaches it.', danger: 'Silent like ExplodMax - no console warning when the limit is hit, text simply stops appearing.' },
  { sec: 'Config', key: 'TickInterpolation', type: 'bool', def: '1', applies: 'both', group: 'Display', does: 'When the render loop runs ahead of the fixed 60Hz game logic, System.tickInterpolation (src/system.go:2592) returns the fractional progress through the current tick (clamped 0..1) and draw positions are interpolated by it.', danger: 'Harmless. Turning it off just makes motion look choppy above 60Hz; it changes nothing about game state.' },
  { sec: 'Config', key: 'ZoomActive', common: true, type: 'bool', def: '1', applies: 'both', group: 'Display', does: 'Master gate on camera zoom. Camera.zoomEnabled (src/camera.go:605) returns `ZoomActive && (c.zoomin != 1 || c.zoomout != 1 || c.autoZoom)` - so with this off, no zoom path runs at all.', danger: 'Carries sync:"host", so in netplay the host\'s value is pushed onto the guest for the session - a guest who turned zoom off will still get the host\'s zoom. Turning it off also silently defeats Debug.ForceStageAutoZoom.' },
  { sec: 'Config', key: 'EscOpensMenu', type: 'bool', def: '1', applies: 'both', group: 'Controls', does: 'Decides what Esc does during a match. System.escExit (src/system.go:1611) returns true - meaning leave the match - when Esc is pressed and either the current gameParams has no pause menu, or this key is off, or attract mode is running with 0 credits.', danger: 'Carries sync:"host" - the host\'s setting governs the session. Note that attract mode with zero credits forces the exit path regardless of this key, so it cannot be used to trap a player in an attract build.' },
  { sec: 'Config', key: 'VsScreenLoading', type: 'bool', def: '0', applies: 'both', group: 'Loading', does: 'When on, character and stage assets load in the background while the VS screen plays (start.lua:3958 sets bgLoading from it, start.lua:4313 branches on it) and loadStart skips its "every team member is selected" precondition check (src/script.go:4970).', danger: 'On the single-threaded web build there is no spare thread to load on, so background loading during the VS screen steals frames from the VS animation rather than hiding the wait.' },
  { sec: 'Config', key: 'TurnsLoading', type: 'bool', def: '0', applies: 'both', group: 'Loading', does: 'In Turns mode, load only the member who is fighting and preload the next during the match. System.startNextTurnsPreload is called per round when set (src/system.go:4040), Char.bgLoadedTurnsRoot (char.go:3693) marks such a root, and the select screen changes how many members it demands before…', danger: 'Under rollback it adds a synchronization step: system.go:4043 calls finishTurnsPreloadForRollback and refuses to advance the round until the preload completes, so a slow disk (or the web VFS) stalls the round transition for both peers.' },
  { sec: 'Config', key: 'BootLoadingMode', type: 'enum', def: '0', applies: 'both', group: 'Loading', opts: [['0', 'Preload everything up front'], ['1', 'Background, wait before select'], ['2', 'Background, never wait']], does: 'Chooses when portraits, palettes and stage previews are loaded. At 0 the engine preloads every character and stage inline while building the select list and panics on failure ("failed to preload", src/system.go:5484); above 0 it creates empty sffs, adds only the declared preload sprites, and hands…', danger: 'At 0 a single broken character def panics the whole engine at boot (system.go:5484) instead of being skipped later - so a permissive roster wants 1 or 2.' },
  { sec: 'Config', key: 'WindowTitle', type: 'string', def: 'Ikemen GO', applies: 'desktop', group: 'Branding', does: 'The SDL window caption (src/system_sdl.go:31, 123, 151) and, after sanitizing, the filename prefix for F12 screenshots: image.go:2257 strips <>:"/\\|?* to underscores, trims and replaces spaces, falls back to "ikemen" if the result is empty, then writes "<title>NNN.png" (image.go:2266).', danger: 'None. It carries no sync tag so peers may differ. On web the browser tab title is set by the host page (dist-fadefix/index.html:74 sets document.title from the build metadata), so this key has no visible effect there, and screenshots never…' },
  { sec: 'Config', key: 'WindowIcon', type: 'string', def: 'external/icons/IkemenCylia_256.png, external/icons/IkemenCylia_96.png, external/icons/IkemenCylia_48.png', applies: 'desktop', group: 'Branding', does: 'A comma-separated list of image paths. At startup (src/system.go:499-514) each is opened with os.Open and decoded with image.Decode, and the whole set is handed to SDL\'s window.SetIcon so the OS picks the best size.', danger: 'A missing or unreadable path is FATAL: system.go:505-509 shows an error dialog and panics with "Icon file can not be found".' },
  { sec: 'Config', key: 'ScreenshotFolder', type: 'string', def: '', applies: 'desktop', group: 'Branding', does: 'A prefix pasted onto the F12 screenshot filename - image.go:2266 formats "%s%s%03d.png" from ScreenshotFolder, the sanitized WindowTitle and a counter.', danger: 'The engine never creates this directory - there is no MkdirAll for it anywhere in src/ - and os.Create\'s error is discarded (`file, _ := os.Create(filename)` at image.go:2268).' },
  { sec: 'Config', key: 'TrainingChar', type: 'string', def: '', applies: 'both', group: 'Training', does: 'A character def path automatically loaded as P2 in Training mode. main.lua:2459 looks it up case-insensitively in main.t_charDef and sets main.forceChar[2].', danger: 'A path that does not resolve to a loadable def is still injected into the roster by main.lua:1694 and only fails when Training actually starts.' },
  { sec: 'Config', key: 'TrainingStage', type: 'string', def: '', applies: 'both', group: 'Training', does: 'A stage automatically loaded in Training. When non-empty, main.lua:2466 suppresses the stage select menu (main.stageMenu stays false) and start.lua:493 resolves the path through start.f_getStageRef.', danger: 'Blank does not fully mean "behave normally" - see commentWrong. If set to a path f_getStageRef cannot resolve, Training starts with whatever that returns rather than a clear error.' },
  { sec: 'Config', key: 'GamepadMappings', type: 'string', def: 'external/gamecontrollerdb.txt', applies: 'desktop', group: 'Controls', does: 'Path to an SDL_GameControllerDB-format mapping file. Read once at startup (src/system.go:418) and each line passed to sdl.GameControllerAddMapping (src/input_sdl.go:261-271). A missing file only calls LogMessage and returns - it is not fatal.', danger: 'Harmless when wrong - a bad path is logged and skipped. Not applicable to the web build: DEVLOG.md records that the browser port uses js-tagged input_js.go and remaps the W3C Gamepad API "standard" mapping itself (DEVLOG.md:118, :641), so…' },
  { sec: 'Config', key: 'LegacyTime', type: 'bool', def: '0', applies: 'both', group: 'Match rules', does: 'Restores MUGEN\'s round-timer arithmetic, in two places. FightScreenTime.draw (src/fightscreen.go:2327) divides remaining ticks by framesPerCount with integer truncation instead of math.Ceil, so the displayed number - including "0" - is held for a full count longer.', danger: 'Carries sync:"host", so the host\'s setting governs a netplay session - a guest expecting modern timing gets legacy timing and a round that runs slightly long.' },
  { sec: 'Sound', key: 'SampleRate', type: 'enum', def: '44100', applies: 'both', group: 'Audio > Engine', opts: [['22050', '22050 Hz - half the DSP work, double the latency'], ['44100', '44100 Hz'], ['48000', '48000 Hz']], advanced: 'It is a device knob, not a game setting. rc.5\'s own options.lua has it commented out (options.lua:200) and it is not in the needReload set, so nothing tells a player a restart is needed. A content manager exposing it gains nothing audible and inherits a nasty failure mode.', does: 'Opens the SDL audio device at this rate once at boot (system.go:474 -> audio_sdl.go:42, sdl.AudioSpec.Freq) AND is re-read live as the destination rate of every beep.Resample call for BGM and every SFX (sound.go:427, 599, 647, 1036, 1089), plus it is the time constant in the Normalizer\'s filter…', danger: 'The device is opened once at boot but the resamplers recompute from the LIVE value, so changing it in-session (or letting a persisted config disagree with the boot value) permanently pitch- and speed-shifts every sound and every BGM by the…' },
  { sec: 'Sound', key: 'SoundFont', type: 'string', def: 'sound/soundfont.sf2', applies: 'both', group: 'Audio > Music', does: 'Path passed to os.Open + midi.NewSoundFont (sound.go:542-553) and used ONLY when a BGM file has a .mid/.midi extension (sound.go:381) — and again inside the BGMRAMBuffer re-decode goroutine (sound.go:494). Nothing else in the engine touches it.', danger: 'Only breaks MIDI BGM (silent track + a log line); it cannot break a build that ships ogg/mp3/wav/flac. But a MIDI track with no valid soundfont fails silently from the player\'s point of view — the stage just has no music.' },
  { sec: 'Sound', key: 'StereoEffects', type: 'bool', def: '1', applies: 'both', group: 'Audio > Effects', does: 'Single gate at sound.go:933: when true (and the sound has a position or a pan value) SoundEffect.Stream computes a left/right split from the sound\'s x position against the camera viewport; when false lv and rv both stay at the sound\'s flat volume.' },
  { sec: 'Sound', key: 'PanningRange', type: 'float', def: '30', applies: 'both', group: 'Audio > Effects', min: 0, max: 100, does: 'Scales the stereo split computed in SoundEffect.Stream: sc = PanningRange/100, of = (100-PanningRange)/200, then lv = clamp(volume*2*(r*sc+of), 0, 512) and rv the mirror (sound.go:952-955).', danger: 'At high values a sound near a screen edge is amplified 2x on the near channel (the formula multiplies by 2 before applying the split), which can clip on packs whose SFX are already hot. Dead only if StereoEffects = 0.' },
  { sec: 'Sound', key: 'WavChannels', type: 'int', def: '32', applies: 'both', group: 'Audio > Engine', min: 1, max: 256, does: 'Two jobs. (1) Lazily sizes each per-player SFX voice pool — char.go:6452 requests from sys.charSoundChannels[playerNo], and SoundChannels.Request grows the slice to WavChannels on first use (sound.go:1165-1166); system/lifebar sounds use the separate sys.soundChannels pool (system.go:229).', danger: 'Job (2) is the real hazard. A character that plays on channel 40 with WavChannels = 32 does not get channel 40 — it gets -1, i.e. "any free channel".' },
  { sec: 'Sound', key: 'MasterVolume', common: true, type: 'int', def: '100', applies: 'both', group: 'Audio > Volume', min: 0, max: 100, webDef: '50', does: 'The only true master. Multiplies SFX via wavVolumeMul = 0.5*(WavVolume*MasterVolume*0.0001) in the Normalizer (sound.go:53), multiplies BGM via volume = -5 + BGMVolume*0.06*(MasterVolume/100)*(bgm.bgmVolume/100) in Bgm.UpdateVolume (sound.go:576), and multiplies video/BGV audio the same way…', danger: 'Unclamped and signed. A negative value does NOT mute — it makes wavVolumeMul negative, so the whole SFX bus is phase-inverted and still audible. Values well above 100 clip hard (floatToS16 in audio_sdl.go:31 saturates at +/-1).' },
  { sec: 'Sound', key: 'PauseMasterVolume', type: 'int', def: '100', applies: 'both', group: 'Audio > Volume', min: 0, max: 100, does: 'Scales audio while the game is paused. Per pause it multiplies the BGM volume once (system.go:1027-1031, and again in Bgm.Open / OpenFromStreamer at sound.go:433 and 653 for music started while already paused) and re-scales every playing char SFX channel each paused tick via softenAllSound…', danger: '0 is a special case, not just "silent": it suspends the BGM streamer and all char SFX rather than attenuating them. That is usually what you want, but it reads to a tester as "the music broke when I opened the menu".' },
  { sec: 'Sound', key: 'WavVolume', common: true, type: 'int', def: '80', applies: 'both', group: 'Audio > Volume', min: 0, max: 100, does: 'SFX/voice bus level only. Used in exactly one place: wavVolumeMul = 0.5*(WavVolume*MasterVolume*0.0001), applied inside Normalizer.Stream (sound.go:53) to everything in sys.soundMixer — char SFX, system/lifebar SFX and video audio. BGM is not in that mixer and is unaffected.', danger: 'Unclamped like MasterVolume — negative inverts phase rather than muting. Note the pair carries 6dB of built-in headroom: the 0.5 factor means WavVolume=100 with MasterVolume=100 is 0.5 gain, so "100%" is deliberately not full scale and…' },
  { sec: 'Sound', key: 'BGMVolume', common: true, type: 'int', def: '75', applies: 'both', group: 'Audio > Volume', min: 0, max: 100, does: 'Music bus level only. Feeds Bgm.UpdateVolume: volume = -5 + BGMVolume*0.06*(MasterVolume/100)*(bgm.bgmVolume/100), clamped to <= 1, and the stream is flagged Silent when volume <= -5 (sound.go:569-586). That number is a beep effects.Volume exponent with Base 2, i.e. gain = 2^volume.', danger: 'The response is exponential, not percentage. With MasterVolume=100 and a track at bgm.volume=100, unity gain (2^0) lands at BGMVolume ~= 83, and 100 gives 2^1 = 2x — so a UI labeled "%" will mislead. The shipped 75 is 2^-0.5 ~= 0.71.' },
  { sec: 'Sound', key: 'MaxBGMVolume', type: 'int', def: '100', applies: 'both', group: 'Audio > Music', min: 100, max: 250, does: 'Ceiling AND scale for content-driven music volume. Bgm.UpdateVolume clamps bgm.bgmVolume to it and logs a warning (sound.go:569-572); PlayBGM (bytecode.go:13406) and Lua playBGM (script.go:5443-5461) clamp their volume argument with Min(volume, MaxBGMVolume).', danger: 'Raising it does not just permit louder music — because of the ModifyBGM path it RETROACTIVELY makes existing content louder.' },
  { sec: 'Sound', key: 'AudioDucking', type: 'bool', def: '0', applies: 'both', group: 'Audio > Effects', does: 'Selects which branch of Normalizer.Stream runs (sound.go:55-66). ON: NormalizerLR.process returns a feedback gain per sample and n.mul = min(16, min(lmul, rmul)) is carried into the next sample — an adaptive auto-gain/limiter that boosts quiet passages and rides down loud ones, with the static…', danger: 'Because the feedback gain is capped at 16, a pack with very quiet SFX can get pumped up ~24dB and then clip when a loud hit lands.' },
  { sec: 'Sound', key: 'BGMRAMBuffer', type: 'bool', def: '1', applies: 'desktop', group: 'Audio > Engine', advanced: 'A platform workaround, not a game setting — and the correct value is already determined by which product we are exporting. The exporter should keep forcing it (0 on web) rather than letting a user pick a value that reintroduces a solved bug. Nothing about it is audible when it works.', does: 'After a looped BGM starts, spawns a background goroutine (sound.go:441-536) that re-opens and re-decodes the whole music file into a beep.Buffer and hot-swaps the streamer to a memory seeker, so loop points do not need a disk seek.', danger: 'On our wasm build this must be 0. With 1 (the engine default) the re-read goroutine plus its cross-match cancel/cleanup broke the BGM path after the first track — the field-reported "music plays once then never again" bug.' },
  { sec: 'Sound', key: 'AudioResampleQuality', type: 'int', def: '1', applies: 'both', group: 'Audio > Engine', opts: [['1', '1 - cheapest'], ['2', '2'], ['3', '3'], ['4', '4 - best']], advanced: 'A pure CPU/quality tuning knob with no gameplay or presentation meaning that a builder can evaluate — the kind of thing the engine should decide, not a content manager. If it is ever surfaced it belongs behind an "advanced" flap capped at 4, not as a 1-16 spinner.', does: 'The quality argument to every beep.Resample in the engine — BGM open (sound.go:428), BGM-from-stream (sound.go:648), each SFX play (sound.go:1037) and video audio (video_ffmpeg.go:215). Higher = wider sinc kernel = more CPU per sample.', danger: 'On our single-threaded wasm build this is the one Sound key with a real frame-time cost: the resampler is inserted unconditionally on every SFX voice and every BGM stream (even when source and destination rates are equal), so with…' },
  { sec: 'Arcade', key: 'AI.RandomColor', type: 'bool', def: '0', applies: 'both', group: 'AI palettes', does: 'In every mode NOT flagged main.rotationChars, this picks how start.f_selectPal (start.lua:610) colors any character whose palette was not chosen by a player button press - CPU opponents, randomly-filled roster slots, forceChar/launchFight entries: 0 = first still-unused entry of the char\'s…' },
  { sec: 'Arcade', key: 'AI.SurvivalColor', type: 'bool', def: '1', applies: 'both', group: 'AI palettes', does: 'Same palette-selection switch as AI.RandomColor but consulted only in modes that set main.rotationChars = true - which in rc.5 is exactly `survival` and `survivalcoop`: 0 = first unused pal.defaults entry, 1 = random unused palette from the char\'s full list.' },
  { sec: 'Arcade', key: 'AI.Ramping', common: true, type: 'bool', def: '1', applies: 'both', group: 'AI ramping', does: 'Gates only the APPLICATION of the ramp offset in start.f_remapAI (start.lua:254): when 1 the per-match value t_aiRamp[matchNo()] minus Options.Difficulty is passed as `offset` into start.f_difficulty; when 0 the offset is 0 and every CPU runs at flat Options.Difficulty.', danger: 'Turning it off does NOT stop the ramp table being built. start.f_aiRamp(1) is called unconditionally whenever the MODE sets main.aiRamp (start.lua:1821), so a custom mode with no entry in start.t_aiRampData still hits…' },
  { sec: 'Arcade', key: 'arcade.AIramp.start', type: 'pair', def: '2, 0', applies: 'both', group: 'AI ramping', does: '(start_match, start_diff) for the \'single\' ramp table, read by start.t_aiRampData.arcade and shared by game modes arcade, timeattack, teamcoop and netplayteamcoop whenever the CPU side (start.p[2]) is in Single team mode: the CPU sits at AI level clamp(Options.Difficulty + start_diff, 1, 8) until…', danger: 'If end_match <= start_match the linear segment is unreachable (the `elseif i-1 <= end_match` can never be true), so difficulty steps straight from start_diff to end_diff - no crash, and no division by zero is possible.' },
  { sec: 'Arcade', key: 'arcade.AIramp.end', type: 'pair', def: '4, 2', applies: 'both', group: 'AI ramping', does: '(end_match, end_diff) for the same \'single\' table: from start_match to end_match wins the AI level interpolates linearly from clamp(Difficulty+start_diff,1,8) to clamp(Difficulty+end_diff,1,8), and after end_match wins it stays at the end value for the rest of the ladder.', danger: 'Setting end_match far beyond the roster length means the ladder ends before the ramp does, so end_diff is never reached. Setting end_match <= start_match makes the ramp a step rather than a slope. Neither breaks the build.' },
  { sec: 'Arcade', key: 'team.AIramp.start', type: 'pair', def: '1, 0', applies: 'both', group: 'AI ramping', does: '(start_match, start_diff) for the \'team\' ramp table, selected by the same start.t_aiRampData.arcade function when start.p[2].teamMode is Simul (1), Turns (2) or Tag (3) - so it covers arcade, timeattack, teamcoop and netplayteamcoop played against a CPU team.', danger: 'Same shape as the arcade pair - a step instead of a slope if end_match <= start_match, and a ramp that never starts if start_match exceeds the roster. Nothing fatal.' },
  { sec: 'Arcade', key: 'team.AIramp.end', type: 'pair', def: '3, 2', applies: 'both', group: 'AI ramping', does: '(end_match, end_diff) for the team table: the AI level finishes its linear climb at clamp(Options.Difficulty + end_diff, 1, 8) once end_match matches are won and holds there.', danger: 'As above - unreachable ramp if end_match is set past the ladder length; step-function if end_match <= start_match.' },
  { sec: 'Arcade', key: 'survival.AIramp.start', type: 'pair', def: '0, -3', applies: 'both', group: 'AI ramping', does: '(start_match, start_diff) for the survival ramp table, read by start.t_aiRampData.survival and shared by survival, survivalcoop and netplaysurvivalcoop - the default -3 deliberately starts the ladder BELOW the chosen difficulty so a long survival run opens easy.', danger: 'Two survival-specific traps. (1) On a select.def roster declaring infinite matches (maxmatches -1), start.lua:1832 regenerates the roster mid-run and calls f_aiRamp(matchNo()) again; f_aiRamp only clears t_aiRamp when currentMatch == 1, so…' },
  { sec: 'Arcade', key: 'survival.AIramp.end', type: 'pair', def: '16, 4', applies: 'both', group: 'AI ramping', does: '(end_match, end_diff) for survival: the AI level climbs linearly across matches until end_match wins, ending at clamp(Options.Difficulty + end_diff, 1, 8) - at the default Difficulty 4 that is level 8, the engine maximum - and holds there for every remaining match.', danger: 'Raising end_match well past 16 on an infinite-roster survival run exposes the append-drift bug described on survival.AIramp.start, where the regenerated tail of t_aiRamp holds values for lower match indices than it is read at - the ladder…' },
  { sec: 'Input', key: 'ButtonAssist', type: 'bool', def: '1', applies: 'both', group: 'Controls', does: 'In InputReader.LocalInput (src/input.go:471) the 9 button states (a,b,c,x,y,z,s,d,w) are passed through ButtonAssistCheck (src/input.go:634), which returns `prevFrame[i] || (current[i] && anyButtonHeldLastFrame)` and then stores the current frame as the new buffer — i.e. every fresh button press is…', danger: 'Cannot break a build. Worth knowing: the delayed set includes `s` (Start), so the pause button also gains a frame in-match.' },
  { sec: 'Input', key: 'SOCDResolution', type: 'enum', def: '4', applies: 'both', group: 'Match rules', opts: [['0', 'Pass both through'], ['1', 'Last pressed wins'], ['2', 'Fixed priority (U over D, F over B)'], ['3', 'First pressed wins'], ['4', 'Suppress both']], does: 'Selects how simultaneous opposing directions are resolved in InputReader.SocdResolution (src/input.go:497). 0 = pass both through, 1 = the later-pressed direction wins, 2 = fixed priority (U over D, F over B), 3 = the first-pressed direction wins, 4 = both are suppressed.', danger: 'Not build-breaking — the clamp makes every out-of-range value land on 4. Mode 0 is the only one with real behavioral risk: allowing both cardinals at once can make some ported characters\' command detection or walk state misbehave, which is…' },
  { sec: 'Input', key: 'ControllerStickSensitivity', type: 'float', def: '0.5', applies: 'both', group: 'Controls', does: 'Threshold above which an analog axis counts as a digital direction press. Three consumers: (a) handleAxisBtn in src/input.go:245-247, for sticks bound as buttons — and it covers the RIGHT stick as well as the left; (b) CheckAxisForDpad in src/input_sdl.go:370-391, the key-config capture screen; (c)…', danger: 'Yes, this one can ship a broken build because nothing clamps it. Set above 1.0 and no stick can ever cross the threshold: the pad goes dead in menus and in the key-config screen too, so the player cannot rebind their way out of it.' },
  { sec: 'Input', key: 'XinputTriggerSensitivity', type: 'float', def: '0.5', applies: 'both', group: 'Controls', does: 'Threshold above which a shoulder trigger bound as a button registers as pressed. Exactly one consumer: handleAxisBtn in src/input.go:241, which short-circuits for axis 4 (LT) and axis 5 (RT) and returns `val > XinputTriggerSensitivity` before the stick logic runs.', danger: 'Same unclamped footgun as the stick value: above 1.0 the triggers can never fire (yet still bind cleanly in the config screen, which makes it look like a game bug), at or below 0 they read as permanently held. Clamp the editable range.' },
  { sec: 'Input', key: 'UiRepeatDelay', type: 'int', def: '30', applies: 'both', group: 'Controls', min: 0, max: 600, does: 'Frames a direction must be held before menu auto-repeat starts. System.uiRepeatShouldFire (src/system.go:1269) returns false while `held < 1+UiRepeatDelay`, so with the default the first repeat lands on hold frame 31.', danger: 'Cannot break a build; the floor at 0 keeps it safe. At 0 the cursor starts stepping almost as soon as a direction is held, which makes picking one entry out of a list fiddly.' },
  { sec: 'Input', key: 'UiRepeatRate', type: 'int', def: '4', applies: 'both', group: 'Controls', min: 1, max: 600, does: 'The period of menu auto-repeat once the delay has elapsed: src/system.go:1278 fires when `(held-(1+UiRepeatDelay)) % UiRepeatRate == 0`, so the default steps the cursor once every 4 frames. Same six directional tokens only.', danger: 'The value itself is safe because of the floor, but note WHY the floor exists: this is the right-hand side of a modulo, and a raw 0 would panic the engine with an integer divide-by-zero on the first held direction in any menu.' },
  { sec: 'Input', key: 'PauseExitDelay', type: 'int', def: '10', applies: 'both', group: 'Controls', does: 'Purely a Lua-side setting; no Go file reads it. When you confirm \'back\' out of the root pause menu (external/script/menu.lua:102) or cancel out of it (menu.lua:300), the script stores this frame count in menu.pauseExitDelay.', danger: 'This is the one genuinely build-breaking key in the section, and nothing validates it. A NEGATIVE value soft-locks the pause menu.' },
  { sec: 'Netplay', key: 'ListenPort', type: 'int', def: '7500', applies: 'desktop', group: 'Netplay', min: 1, max: 65535, does: 'TCP port for the lobby/handshake stream only: NetConnection.Accept() binds it (host) and NetConnection.Connect() dials it (guest) in src/netplay_desktop.go, carrying the "IKEMENGO" handshake, the config-sync exchange, and - in delay netcode - the input stream itself.', danger: 'Not build-breaking. A port under 1024 fails to bind without privileges on Linux/macOS (Accept returns the error up to Lua as a RaiseError); a port already in use fails the same way. Only netplay connectivity is affected, never gameplay.' },
  { sec: 'Netplay', key: 'RollbackNetcode', type: 'bool', def: '1', applies: 'both', group: 'Netplay', does: 'Selects the netcode path. When 1, enterNetPlay creates a RollbackSession (src/script.go:2517) and System.runMatch() hands the whole match loop to rollback.hijackRunMatch() (src/system.go:4053); when 0 the match runs the normal loop and inputs are exchanged lockstep over the TCP connection.', danger: 'It is sync:"strict". If the Studio bakes different values into two players\' builds the session is refused outright with the motif "config" warning naming Netplay.RollbackNetcode - a build that cannot play anyone else\'s build.' },
  { sec: 'Netplay', key: 'Rollback.FrameDelay', type: 'int', def: '2', applies: 'both', group: 'Netplay', does: 'peer.SetFrameDelay(localHandle, N) (src/rollback.go:960, :1009) - inserts N frames of artificial delay into the LOCAL player\'s input queue and feeds the same N to the timesync of every endpoint, so more inputs are confirmed before the frame is simulated and rollbacks become rarer and shorter.', danger: 'No build-breaking failure. High values are pure added input lag; 0 is the jumpiest. Worth surfacing in the UI that it is host-synced - a per-player preference silently loses to the host\'s value once a match starts, so this is a property of…' },
  { sec: 'Netplay', key: 'Rollback.DisconnectNotifyStart', type: 'int', def: '1000', applies: 'both', group: 'Netplay', webDef: '2000', does: 'peer.SetDisconnectNotifyStart (src/rollback.go:959, :1008). After this many ms with no packet from the peer, ggpo queues a NetworkInterruptedEvent which arrives at RollbackSession.OnEvent as EventCodeConnectionInterrupted.', danger: 'Harmless. Setting it above DisconnectTimeout, or to 0, just means the (already invisible) interrupt notice never fires; the hard timeout is unaffected.' },
  { sec: 'Netplay', key: 'Rollback.DisconnectTimeout', type: 'int', def: '3000', applies: 'both', group: 'Netplay', webDef: '8000', does: 'peer.SetDisconnectTimeout (src/rollback.go:958, :1007). After this many ms without a packet, ggpo queues DisconnectedEvent; RollbackSession.OnEvent (src/rollback.go:791-803) then sets sys.endMatch, saves the replay, dumps the state-log ring if LogsEnabled, and sets sessionWarning to the motif\'s…', danger: 'Real. 0 (or an absurdly large value) means a peer that drops never ends the match - both players sit in a frozen session with no warning and no replay saved.' },
  { sec: 'Netplay', key: 'Rollback.LogsEnabled', type: 'bool', def: '0', applies: 'both', group: 'Netplay (diagnostics)', advanced: 'Pure diagnostics - it produces developer logs a player can neither read nor act on, and in the browser build save/logs is an emulated FS path nobody can retrieve. It belongs behind whatever debug switch the Studio already has, not in a content manager.', does: 'Three separate things. (1) Opens save/logs/Rollback-<timestamp>.log (or Rollback-Desync-Test-<timestamp>.log in sync-test mode) and hands it to ggpo via ggpo.EnableLogs()/SetLogger (src/rollback.go:917, :966, :1016).', danger: 'Yes, and it is a genuine crash risk on desktop. InitP1/InitP2/InitSyncTest open the log with os.OpenFile and panic(err) on failure.' },
  { sec: 'Netplay', key: 'Rollback.SaveStageData', type: 'bool', def: '0', applies: 'both', group: 'Netplay', webDef: '1', does: 'Controls how much stage state goes into each rollback save state (src/state.go:235-243). When a rollback session is live (or DesyncTestFrames > 0), the default path saves only the light stage.CloneRollbackState(); setting this to 1 forces the full cloneStageList() of the entire stage list into…', danger: 'Both directions. Off, a stage that mutates through a path canMutateStage does not detect diverges between the two machines and trips a hard desync mid-match - a content-dependent failure the build author is the only one positioned to…' },
  { sec: 'Netplay', key: 'Rollback.DesyncTest', type: 'bool', def: '0', applies: 'neither', group: 'Netplay (diagnostics)', advanced: 'A developer instrument for chasing determinism bugs, not a game rule. It changes no visible behavior except how loudly the engine dies, and it costs a full GameState serialization per saved frame.', does: 'Two effects. (1) SaveGameState returns a real GameState.Checksum() (FNV-1a over GameState.String()) instead of ggpo.DefaultChecksum (src/rollback.go:693-706) - that value is what ggpo\'s offline SyncTest compares against the re-simulated frame.', danger: 'Two ways. ON, every saved frame serializes the whole GameState to a string and hashes it. OFF, the recover() blocks above swallow the panic instead of re-raising it - a panic escaping backend.AdvanceFrame is caught, nothing is logged…' },
  { sec: 'Netplay', key: 'Rollback.DesyncTestFrames', type: 'int', def: '0', applies: 'neither', group: 'Netplay (diagnostics)', min: 0, max: 64, advanced: 'An engine-development harness. It makes single-player behave nothing like single-player, and there is no game-design question it answers.', does: 'Passed to ggpo.NewSyncTest as checkDistance (src/rollback.go:1037). Any non-zero value makes System.usesRollbackMatch() true for OFFLINE play (src/system.go:1603-1610), so every offline match - arcade included - is hijacked into the rollback loop and saves/loads a full GameState every frame; then…', danger: 'The most dangerous key in the section. Non-zero turns every offline match into a rollback re-simulation - enormous slowdown - and note it does this regardless of RollbackNetcode, so even a build with rollback disabled is affected.' },
  { sec: 'Netplay', key: 'Rollback.DesyncTestAI', type: 'bool', def: '0', applies: 'neither', group: 'Netplay (diagnostics)', advanced: 'Only reachable inside the developer sync-test harness, and it takes the controllers away from the human when it is. Nothing a build author would ever want to set.', does: 'In the offline sync-test path only (guarded by rs.session.syncTest, src/rollback.go:168-176), feeds getAIInputs(0) and getAIInputs(1) into both player handles instead of reading the controllers, so the sync test can run unattended.', danger: 'Inert on its own: the sync-test session is only created when DesyncTestFrames > 0, so with the default 0 this key does nothing at all.' },
  { sec: 'Debug', key: 'AllowDebugMode', type: 'bool', def: '1', applies: 'both', group: 'Debug access', does: 'Backs System.debugModeAllowed() (src/system.go:4425), which returns false outright whenever netConnection or a rollback session is live and otherwise returns this flag; when false the engine early-returns from the Lua debug entry points toggleDebugDisplay, toggleClsnDisplay, toggleWireframeDisplay…', danger: 'Cannot break a build. Setting 0 in a build you are still testing removes the only in-engine view of Clsn boxes and state/anim numbers, which is where invalid-ANIMATION style errors surface.' },
  { sec: 'Debug', key: 'AllowDebugKeys', common: true, type: 'bool', def: '1', applies: 'both', group: 'Debug access', does: 'In OnKeyPressed (src/input.go:136-138) every shortcut registered via addHotkey whose 6th argument is true (ShortcutScript.DebugKey, set at src/script.go:1012) is skipped unless this is set.', danger: 'Cannot break a build. Left at 1 in a release, any player can kill the opponent or fill the power bar from the keyboard.' },
  { sec: 'Debug', key: 'ClipboardRows', type: 'int', def: '2', applies: 'both', group: 'Debug overlay', min: 0, max: 1000, advanced: 'It sizes a buffer inside a developer overlay. Nobody building a MUGEN-style game needs to set it, and exposing it hands the user a crash (see danger).', does: 'Caps each character\'s clipboardText ring - the DisplayToClipboard/AppendToClipboard buffer printed by the Ctrl+D overlay (src/char.go:9686-9688). It is also read in src/system.go:3899 to compute the Y origin of the overlay\'s data block, so it shifts the overlay layout as well as trimming text.', danger: 'A NEGATIVE value panics the engine. char.go guards with `len(clipboardText) > ClipboardRows` and then slices `clipboardText[len-ClipboardRows:]`, so with ClipboardRows = -1 and one buffered line it slices [2:] on a length-1 slice - a…' },
  { sec: 'Debug', key: 'ConsoleRows', type: 'int', def: '15', applies: 'both', group: 'Debug overlay', min: 0, max: 1000, advanced: 'Same as ClipboardRows - a debug overlay buffer size, not a game-design decision, and unclamped enough to be a footgun.', does: 'Caps System.consoleText in appendToConsole (src/system.go:1945-1949), the line ring drawn as the console block of the Ctrl+D overlay. It is fed by printToConsole (CNS/Lua Log output) and by engine warning messages.', danger: 'Negative values panic identically to ClipboardRows: `consoleText[len-ConsoleRows:]` under a `len > ConsoleRows` guard slices past the end. 0 discards every console line, which silently removes the only place some engine warnings appear.' },
  { sec: 'Debug', key: 'ClsnDarken', type: 'bool', def: '1', applies: 'both', group: 'Debug overlay', advanced: 'It only changes the readability of a debug view that is itself gated behind AllowDebugMode. There is no game-facing consequence to set here.', does: 'In FightScreenRound.drawFade (src/fightscreen.go:4152-4159): when no round fade-out or fade-in is active AND sys.clsnDisplay is on, it draws the fade-in\'s rect over the whole screen rect at (0,0), dimming the stage and characters so collision boxes read against the art.' },
  { sec: 'Debug', key: 'DumpLuaTables', type: 'bool', def: '0', applies: 'both', group: 'Developer tools', advanced: 'Pure engine/script diagnostics. The output is only interpretable by someone debugging Ikemen\'s own Lua, and it is never useful to a person assembling a build.', does: 'The engine side is one line: src/main.go:183 creates <baseDir>/debug/ at boot when set. All the actual dumping is script-side - main.lua, start.lua, menu.lua and options.lua call main.f_printTable() into debug/*.txt at load and at each screen transition (loadMotif.txt, t_roster.txt, t_grid.txt…' },
  { sec: 'Debug', key: 'Font', type: 'string', def: 'font/debug.def', applies: 'desktop', group: 'Debug overlay', does: 'main.lua:642 calls loadDebugFont(Debug.Font, Debug.FontScale). src/script.go:4314-4332 builds a TextSprite from loadFnt(path, -1) and assigns it to sys.debugFont - the single face used for the entire Ctrl+D overlay (per-character state/anim data, the clipboard block and the console block).', danger: 'HIGH, and it is a boot-time kill. loadFnt failure raises a Lua error via l.RaiseError inside main.lua\'s top-level chunk, and src/main.go:201 does panic(err) on any DoFile error - so a missing or misspelled Debug.Font path takes the engine…' },
  { sec: 'Debug', key: 'FontScale', type: 'float', def: '0.5', applies: 'desktop', group: 'Debug overlay', does: 'Second argument to loadDebugFont; src/script.go:4327-4329 sets the debug TextSprite\'s xscl and yscl to this value uniformly, and only if the argument is non-nil (omitting it leaves the sprite\'s default scale).', danger: 'No crash, but it is tightly coupled to Font. 0.5 is tuned for the 24px TrueType default face; applied to a 5x8 bitmap glyph it renders sub-pixel mush that is genuinely unreadable - which is exactly why mugen-web pairs its bitmap-font…' },
  { sec: 'Debug', key: 'StartStage', common: true, type: 'string', def: 'stages/stage0-720.def', applies: 'both', group: 'Content defaults', does: 'Two distinct jobs, only one of which is debug. (a) main.lua:1741-1746 - if select.def contributed no stages to either team\'s include list, this stage is added and becomes the build\'s only stage; it is the stage-of-last-resort for the whole roster.', danger: 'Real. A bad path plus an empty select.def leaves the build with no selectable stage (main.f_addStage returns nil on failure, so the nil is inserted into t_includeStage and the roster ends up stageless).' },
  { sec: 'Debug', key: 'ForceStageZoomout', type: 'float', def: '0', applies: 'both', group: 'Stage camera overrides', advanced: 'The ini comment itself says "This is a debug parameter and may be removed in future versions" - exposing a knob the engine has announced it may delete is a maintenance trap.', does: 'src/stage.go:1231-1238 - while parsing a stage\'s [Camera] section, IF the stage\'s own zoomin AND zoomout are both still the default 1, a nonzero value here replaces stageCamera.zoomout (the maximum zoom-out factor).', danger: 'Set in a shipped build it retunes every stage that was authored with the default camera, so stages look wrong in a way that is very hard to trace back to a config key. It also flips the meaning of ForceStageAutoZoom (see that key).' },
  { sec: 'Debug', key: 'ForceStageZoomin', type: 'float', def: '0', applies: 'both', group: 'Stage camera overrides', advanced: 'Same reasoning as ForceStageZoomout - self-declared removable debug parameter, and a global override of a per-stage authored value.', does: 'src/stage.go:1231-1235 - same mechanism as ForceStageZoomout but assigns stageCamera.zoomin (maximum zoom-in factor), and only when the stage\'s own zoomin AND zoomout are both still 1. Also read at stage.go:1246 as an alternative satisfying the ForceStageAutoZoom guard.', danger: 'Same as ForceStageZoomout: silently retunes every default-camera stage in the build, and participates in the ForceStageAutoZoom guard hole described under that key.' },
  { sec: 'Debug', key: 'ForceStageAutoZoom', type: 'bool', def: '0', applies: 'both', group: 'Stage camera overrides', advanced: 'Same family as the two Force*Zoom keys: a global rewrite of per-stage camera authoring, and it silently overwrites four further camera values (zoomanchor and the three timing constants) that the key\'s name gives no hint about.', does: 'src/stage.go:1245-1248 - turns stageCamera.autoZoom on for a stage that did NOT declare `autozoom` in its .def, provided (zoomin == 1 OR ForceStageZoomin > 0) AND (zoomout == 1 OR ForceStageZoomout > 0).', danger: 'Beyond retuning the camera, it overwrites zoomanchor and the zoomin delay/speed constants on affected stages. Combined with a nonzero ForceStageZoomout it reaches stages the comment says it will not touch.' },
  { sec: 'Debug', key: 'KeepSpritesOnReload', type: 'bool', def: '0', applies: 'both', group: 'Developer tools', advanced: 'An iteration-speed knob for someone editing a character\'s CNS/AIR in an external editor against a running build. Our Studio users edit content in the Studio and re-export; they never take the Shift+F4 hot-reload path, so the key has no meaning in the product.', does: 'src/script.go:3155-3162 - in the reload path taken after Shift+F4 or the reload() debug hotkey, the engine normally nils sys.cgi[i].sff for each slot flagged in reloadCharSlot so the SFF is re-read from disk. With this set, the sff pointer is kept and the sprite cache is reused.', danger: 'Cannot break a shipped build (the whole code path needs the reload hotkey, which needs AllowDebugMode-era debug access).' },
  { sec: 'Debug', key: 'MacOSUseCommandKey', type: 'bool', def: '1', applies: 'desktop', group: 'Controls', advanced: 'Platform input plumbing that the engine could and arguably should derive from the OS itself. It is not a game-design decision, it is dead on every target except macOS desktop, and a Studio user on Windows or in a browser would be setting something that can never fire.', does: 'src/input_sdl.go:263-268, NewModifierKey - when runtime.GOOS == "darwin" and this is set, every hotkey registered with ctrl=true is matched against sdl.KMOD_GUI (the Command key) instead of sdl.KMOD_CTRL. It rewrites the modifier for ALL Ctrl shortcuts the engine registers, not only the debug ones.', danger: 'None. A wrong value just means Mac users press the modifier they were not expecting.' },
  { sec: 'Debug', key: 'SpeedTest', type: 'int', def: '100', applies: 'desktop', group: 'Developer tools', advanced: 'It is a benchmark-harness knob that is inert without a CLI flag, and it reaches its effect by writing a value that deliberately violates the documented range of another setting.', does: 'Nothing at all unless the executable is launched with the -speedtest command-line flag. main.lua:211-219: when -speedtest is present, target = Debug.SpeedTest (overridden by a numeric argument to the flag if > 0), then setGameSpeed(floor(60 * (target - 1) / Options.GameSpeedStep + 0.5)).', danger: 'Harmless in a shipped build - without the flag it is never read. It is worth knowing that the mechanism can drive Options.GameSpeed far outside its clamped -9..9 range, so anything the Studio does that echoes GameSpeed back into a UI…' },
  { sec: 'Common', key: 'Air', type: 'string', def: 'data/common.air', applies: 'both', group: 'Common files', does: 'Comma-separated list of .air files merged into EVERY character\'s animation table at char load (src/char.go:4311-4337). Each file is parsed against the character\'s OWN sff and palette list (readAction(gi.sff, &gi.palettedata.palList, ...)), so its actions draw with the character\'s local sprites.', danger: 'A path that does not resolve is a HARD error out of Char.load — LoadFile\'s error propagates and the character fails to load, aborting the match (char.go:4333-4336).' },
  { sec: 'Common', key: 'Cmd', type: 'string', def: 'data/common.cmd', applies: 'both', group: 'Common files', does: 'Comma-separated list of .cmd files whose raw TEXT is appended to the character\'s own command-file text before parsing (src/compiler.go:8189-8201), so their [Command] sections are added to every character\'s command list.', danger: 'TWO NON-OBVIOUS TRAPS. (1) [Remap] and [Defaults] in a common cmd file are FIRST-WINS across the whole concatenation — compiler.go:8216 latches `remap, defaults := true, true` and clears each after the first section seen.' },
  { sec: 'Common', key: 'Const', type: 'string', def: 'data/common.const', applies: 'both', group: 'Common files', does: 'Comma-separated list of ini files loaded into gi.constants for EVERY character (src/char.go:3967-3983), after initConstants() installs the engine\'s hardcoded defaults (char.go:7983+) and BEFORE the character\'s own .cns, whose [Constants] block therefore overrides these (char.go:4228).', danger: 'ONLY THE FIRST INI SECTION OF EACH FILE IS READ. char.go:3971-3977 calls ReadIniSection once with i starting at 0, which stops at the next `[`.' },
  { sec: 'Common', key: 'States', type: 'string', def: 'data/functions.zss, data/action.zss, data/demo.zss, data/dizzy.zss, data/guardbreak.zss, data/score.zss, data/system.zss, data/tag.zss, data/training.zss', applies: 'both', group: 'Common files', does: 'Comma-separated list of CNS or ZSS state files compiled into EVERY character, LAST — after the character\'s own st/st0..stN, its cmd file, and its stcommon (common1.cns) (src/compiler.go:8368-8375).', danger: 'THE SILENT ONE: undefined ZSS function calls are a runtime NO-OP with only a console line ("called undefined function", bytecode.go:4524-4527).' },
  { sec: 'Common', key: 'Fx', type: 'string', def: 'data/gofx/gofx.def', applies: 'both', group: 'Effects', does: 'Comma-separated list of FightFX pack .def files, loaded once per match by the Loader before characters (src/system.go:6445-6455 -> loadCommonFightFx, src/fightscreen.go:85-100).', danger: 'A missing file kills the whole match, not one character: loadCommonFightFx\'s error sets Loader state LS_Error (system.go:6448-6452) and the match refuses to start.' },
  { sec: 'Common', key: 'Modules', type: 'string', def: '', applies: 'both', group: 'Modules & scripting', does: 'Comma-separated list of Lua files `require`d once at startup (external/script/main.lua:3984-4000). They are appended AFTER every .lua found by a recursive walk of external/mods/ (getDirectoryFiles is a filepath.Walk, src/script.go:3583-3596) and BEFORE the motif\'s own files.module.', danger: 'UNLIKE EVERY OTHER KEY IN THIS SECTION, these paths are NOT resolved by the engine\'s SearchFile. They go straight to Lua `require`, so they resolve against Lua\'s package.path (the game root) and NOT against the char-dir / motif-dir / data/…' },
  { sec: 'Common', key: 'Lua', type: 'string', def: 'loop()', applies: 'both', group: 'Modules & scripting', advanced: 'This is a raw code-injection point into the frame loop, not a setting. The only correct value for essentially every build is `loop()`, the failure mode for a wrong value is silent (overlays vanish only during the fight) or a mid-match Lua error, and the legitimate way to add per-frame behavior is a…', does: 'Comma-separated Lua source strings executed with luaLState.DoString once per UI tick from System.uiAction (src/system.go:2985-2993), right after the motif is stepped and acted (the ordering is deliberate — see the in-source link to issue #3080, since inverting it lags motif input by a frame).', danger: 'It is DoString, so each string is RE-PARSED AND RE-COMPILED EVERY FRAME — this is a call site, not a place to put a program.' },
];

// What a given product should actually be told, out of what the user chose.
//
// Sparse by design: only values moved off the default are stored, so an
// untouched setting keeps whatever the engine's own default is and a later
// Ikemen release stays free to change it. Writing all 133 every time would pin
// this build to rc.5's values permanently, including the ones nobody picked.
//
// `target` is 'web' or 'desktop'. A setting is written only where it MEANS
// something: shipping Video.Fullscreen to a canvas, or a browser workaround to
// a native renderer, is how a config comes to look configured and behave as
// though it is not.
// What this key is already set to in a given product if nobody touches it.
// `webDef` exists because the website's baseline is our tuned config, not the
// engine's: on the web a GameWidth of 854 is the default and 1280 is a real
// change, while on desktop it is the other way round.
function defaultFor(s, target) {
  return (target === 'web' && s.webDef !== undefined) ? s.webDef : s.def;
}

// Is this value redundant EVERYWHERE it would be written? Only then is it safe
// to forget - a value matching one product's default can be a deliberate change
// in the other, and dropping it there loses the choice silently.
function isDefaultEverywhere(s, val) {
  const targets = s.applies === 'both' ? ['web', 'desktop'] : [s.applies];
  return targets.every((t) => String(val) === String(defaultFor(s, t)));
}

// `complete` asks for EVERY key this target can carry, filling an absent one
// from its default, instead of only the ones the user has overridden.
//
// WHY THAT MATTERS, and it is not a nicety. roster.settings is stored SPARSE:
// server.js drops a key the moment its value returns to the default. The
// desktop export then merges only the keys it was given into the config that is
// already in the destination folder - so setting Fullscreen on, exporting,
// turning it off, and exporting again left the build FULLSCREEN, with no way to
// ever clear it. The panel said one thing and the build did another, and a
// fresh folder was correct while the folder you actually use was not. Writing
// the full set makes the exported config always equal what the panel shows.
//
// It is the same shape as Motif being written only into an empty folder.
function settingsFor(values, target, complete) {
  const out = [];
  for (const s of SETTINGS) {
    const path = s.sec + '.' + s.key;
    const v = (values || {})[path];
    const set = !(v === undefined || v === null || v === '');
    if (!set && !complete) continue;
    if (s.applies !== 'both' && s.applies !== target) continue;
    let val = String(set ? v : defaultFor(s, target));
    // A DEFAULT IS NOW SOMETHING WE WRITE, so it has to be a real value.
    //
    // `complete` exists because an export could not UN-set a setting - it only
    // ever wrote overrides, so clearing one in the Studio left the previous
    // value in the build. Writing the whole set fixed that and made every
    // default load-bearing, which turned four documentation placeholders into
    // live values: Video.ExternalShaders shipped as the literal string
    // "(empty)", the engine parsed that []string as one entry and died in
    // newWindow with `open (empty).vert: The system cannot find the file
    // specified`. A black window and a dialog, on a desktop export.
    //
    // The four are fixed at the source above. This is the guard that stops the
    // next one: a value that only ever appeared in a comment column must never
    // reach a config file.
    if (!set && /^\((?:empty|blank|none|default|unset|blank\s*by\s*default)\)$/i.test(val.trim())) {
      val = '';
    }
    out.push({ sec: s.sec, key: s.key, def: s, fromDefault: !set, val });
  }

  // WINDOWWIDTH AND WINDOWHEIGHT GO TOGETHER OR NOT AT ALL.
  //
  // The engine's guard is `if WindowWidth > 0 || WindowHeight > 0` - an OR, not
  // an AND - so setting one of the pair and leaving the other at its default 0
  // does not fall back to GameWidth/GameHeight as the ini's comment claims. It
  // builds a window with a zero dimension. Anyone setting a window width means
  // to size the window, not to destroy it, so the partner is filled in from the
  // render size rather than handing the engine a value that cannot work.
  const win = { WindowWidth: 'GameWidth', WindowHeight: 'GameHeight' };
  const has = (k) => out.some((o) => o.sec === 'Video' && o.key === k);
  for (const [k, from] of Object.entries(win)) {
    const other = k === 'WindowWidth' ? 'WindowHeight' : 'WindowWidth';
    if (!has(k) && has(other)) {
      const src = SETTINGS.find((x) => x.sec === 'Video' && x.key === from);
      const chosen = (values || {})['Video.' + from];
      out.push({ sec: 'Video', key: k, def: SETTINGS.find((x) => x.sec === 'Video' && x.key === k),
        val: String(chosen !== undefined && chosen !== '' ? chosen : defaultFor(src, target)) });
    }
  }
  return out;
}

module.exports = { SETTINGS, settingsFor, defaultFor, isDefaultEverywhere };
